DROP TABLE IF EXISTS `listing_master_v2`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `listing_master_v2` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `business_name` varchar(255) NOT NULL,
  `category` varchar(100) DEFAULT NULL,
  `state` varchar(100) DEFAULT NULL,
  `district` varchar(150) DEFAULT NULL,
  `city` varchar(150) DEFAULT NULL,
  `address` text,
  `phone` varchar(50) DEFAULT NULL,
  `latitude` decimal(10,7) DEFAULT NULL,
  `longitude` decimal(10,7) DEFAULT NULL,
  `source` varchar(100) DEFAULT NULL,
  `osm_type` varchar(20) DEFAULT NULL,
  `osm_id` bigint DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_osm_listing` (`osm_type`,`osm_id`),
  KEY `idx_state` (`state`),
  KEY `idx_district` (`district`),
  KEY `idx_city` (`city`),
  KEY `idx_category` (`category`)
) ENGINE=InnoDB AUTO_INCREMENT=45662 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
